def lowestCommonAncestor(root, p, q):
    def path(n, t):
        if not n:
            return None
        if n is t:
            return [n]
        sub = path(n.left, t) or path(n.right, t)
        return [n] + sub if sub else None
    a, b = path(root, p), path(root, q)
    res = None
    for x, y in zip(a, b):
        if x is y:
            res = x
        else:
            break
    return res

